#!/usr/bin/env bash
# Copyright 2026 The Kuicksilver Authors
# SPDX-License-Identifier: Apache-2.0
# Generates the test PKI (100-year validity) as DER files for the C tests and as TestCerts.kt for commonTest.
# Requires a host openssl >= 3.0 (not our stripped build). Usage: gen-testcerts.sh
set -euo pipefail
root="$(cd "$(dirname "$0")/../.." && pwd)"
der="$root/kuicksilver-native/src/c/test/testdata"; kt="$root/kuicksilver-tls/src/commonTest/kotlin/io/kuicksilver/tls/TestCerts.kt"; kt2="$root/kuicksilver-native/src/commonTest/kotlin/io/kuicksilver/native/TestCerts.kt"; kt3="$root/kuicksilver-ktor-network/src/commonTest/kotlin/io/kuicksilver/tls/TestCerts.kt"; kt4="$root/kuicksilver-quic/src/commonTest/kotlin/io/kuicksilver/quic/TestCerts.kt"; kt5="$root/kuicksilver-testing/src/commonTest/kotlin/io/kuicksilver/testing/TestCerts.kt"; kt6="$root/kuicksilver-bench/src/commonMain/kotlin/io/kuicksilver/bench/TestCerts.kt"
O="${OPENSSL:-$(command -v openssl)}"; "$O" version | grep -q 'OpenSSL 3' || { echo "need OpenSSL 3.x CLI"; exit 2; }
work=$(mktemp -d); trap 'rm -rf "$work"' EXIT INT TERM HUP; cd "$work"; mkdir -p "$der"; rm -f "$der"/*.der
DAYS=36500
ca() { # name [subject]
  "$O" req -x509 -newkey ec -pkeyopt ec_paramgen_curve:P-256 -nodes -keyout "$1.key" -out "$1.pem" -days $DAYS -subj "/CN=${2:-$1}" \
    -addext "basicConstraints=critical,CA:TRUE" -addext "keyUsage=critical,keyCertSign" 2>/dev/null
  "$O" x509 -in "$1.pem" -outform DER -out "$der/$1.der"
}
leaf() { # name issuer cn san eku [extra-days-args] [keyfile-to-reuse]
  local name=$1 issuer=$2 cn=$3 san=$4 eku=$5 dates=${6:-} key=${7:-}
  if [ -n "$key" ]; then cp "$key" "$name.key"; else "$O" ecparam -name prime256v1 -genkey -noout -out "$name.key"; fi
  "$O" req -new -key "$name.key" -out "$name.csr" -subj "/CN=$cn" 2>/dev/null
  { echo "basicConstraints=CA:FALSE"; echo "keyUsage=digitalSignature"; [ -n "$eku" ] && echo "extendedKeyUsage=$eku"; [ -n "$san" ] && echo "subjectAltName=$san"; } > "$name.ext"
  # shellcheck disable=SC2086
  "$O" x509 -req -in "$name.csr" -CA "$issuer.pem" -CAkey "$issuer.key" -CAcreateserial -out "$name.pem" $dates -extfile "$name.ext" 2>/dev/null
  "$O" x509 -in "$name.pem" -outform DER -out "$der/$name.der"; "$O" pkcs8 -topk8 -nocrypt -in "$name.key" -outform DER -out "$der/$name.key.der"
}
ca test-ca "Kuicksilver Test CA"; ca other-ca "Other CA"
# intermediate signed by test-ca
"$O" ecparam -name prime256v1 -genkey -noout -out intermediate.key
"$O" req -new -key intermediate.key -out intermediate.csr -subj "/CN=Test Intermediate" 2>/dev/null
printf 'basicConstraints=critical,CA:TRUE,pathlen:0\nkeyUsage=critical,keyCertSign\n' > intermediate.ext
"$O" x509 -req -in intermediate.csr -CA test-ca.pem -CAkey test-ca.key -CAcreateserial -out intermediate.pem -days $DAYS -extfile intermediate.ext 2>/dev/null
"$O" x509 -in intermediate.pem -outform DER -out "$der/intermediate.der"
leaf server test-ca server.test "DNS:server.test,DNS:*.wild.test,IP:127.0.0.1,IP:::1" serverAuth "-days $DAYS"
leaf server-dns-ip test-ca x "DNS:127.0.0.1" serverAuth "-days $DAYS"
leaf server-cn-only test-ca cn.test "" serverAuth "-days $DAYS"
leaf server-partial-wildcard test-ca x "DNS:f*.wild.test" serverAuth "-days $DAYS"
leaf server-no-eku test-ca server.test "DNS:server.test" "" "-days $DAYS"
leaf server-client-eku test-ca server.test "DNS:server.test" clientAuth "-days $DAYS"
leaf server-other-key test-ca server.test "DNS:server.test" serverAuth "-days $DAYS"
leaf server-other-ca other-ca server.test "DNS:server.test" serverAuth "-days $DAYS"
leaf server-via-intermediate intermediate server.test "DNS:server.test" serverAuth "-days $DAYS"
big=$(for i in $(seq 1 700); do printf 'DNS:name%04d.big.test,' "$i"; done; printf 'DNS:server.test')
leaf server-big-chain intermediate server.test "$big" serverAuth "-days $DAYS"
leaf proxy test-ca proxy.internal "DNS:proxy.internal" serverAuth "-days $DAYS"
leaf expired test-ca server.test "DNS:server.test" serverAuth "-not_before 20000101000000Z -not_after 20010101000000Z"
leaf not-yet-valid test-ca server.test "DNS:server.test" serverAuth "-not_before 21000101000000Z -not_after 21010101000000Z"
leaf client test-ca client.test "DNS:client.test" clientAuth "-days $DAYS"
leaf client-no-eku test-ca client.test "DNS:client.test" "" "-days $DAYS"
leaf client-other-ca other-ca client.test "DNS:client.test" clientAuth "-days $DAYS"
# SPKI SHA-256 of the server leaf, for pin tests
"$O" x509 -in server.pem -pubkey -noout | "$O" pkey -pubin -outform DER | "$O" dgst -sha256 -binary | base64 > "$der/server.spki.sha256.b64"
# Kotlin constants
mkdir -p "$(dirname "$kt")"
{
  printf '// Copyright 2026 The Kuicksilver Authors\n// SPDX-License-Identifier: Apache-2.0\n// generated by tools/certs/gen-testcerts.sh — do not edit\n@file:Suppress("ktlint", "MaxLineLength")\n\npackage io.kuicksilver.tls\n\nimport kotlin.io.encoding.Base64\n\n/** Test PKI shared by all platforms (100-year validity, P-256). */\npublic object TestCerts {\n    private fun b64(s: String): ByteArray = Base64.decode(s)\n'
  for f in "$der"/*.der; do n=$(basename "$f" .der | perl -pe 's/\.key$/Key/; s/-([a-z])/\u$1/g'); printf '    public val %s: ByteArray by lazy { b64("%s") }\n' "$n" "$(base64 < "$f" | tr -d '\n')"; done
  printf '    public val serverSpkiSha256: ByteArray by lazy { b64("%s") }\n' "$(tr -d '\n' < "$der/server.spki.sha256.b64")"
  printf '    /** PEM encoding helper for tests. */\n    public fun toPem(type: String, der: ByteArray): String = "-----BEGIN $type-----\\n" + Base64.encode(der).chunked(64).joinToString("\\n") + "\\n-----END $type-----\\n"\n}\n'
} > "$kt"
mkdir -p "$(dirname "$kt2")" "$(dirname "$kt3")" "$(dirname "$kt4")"; sed "s/^package io.kuicksilver.tls$/package io.kuicksilver.native/" "$kt" > "$kt2"; cp "$kt" "$kt3"; sed "s/^package io.kuicksilver.tls$/package io.kuicksilver.quic/" "$kt" > "$kt4"; mkdir -p "$(dirname "$kt5")"; sed "s/^package io.kuicksilver.tls$/package io.kuicksilver.testing/" "$kt" > "$kt5"; mkdir -p "$(dirname "$kt6")"; sed -e "s/^package io.kuicksilver.tls$/package io.kuicksilver.bench/" -e "s/^public object TestCerts/internal object TestCerts/" -e "s/^    public /    internal /" "$kt" > "$kt6"
echo "generated $(ls "$der"/*.der | wc -l | tr -d ' ') DER files and $kt"
